import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
// A person signs in with Google and uploads a video to their channel, as YouTube's server-side web app guide has an
// application do it (https://developers.google.com/youtube/v3/guides/auth/server-side-web-apps): Google's authorize page,
// the account the person chooses, the code traded for an access token and a refresh token at Google's token endpoint,
// then the YouTube Data API with the token; the refresh token renews it. Readback reads the video with the project's
// API key, writing nothing.
const clientId = process.env.GOOGLE_CLIENT_ID;
const clientSecret = process.env.GOOGLE_CLIENT_SECRET;
const channelId = process.env.YOUTUBE_CHANNEL_ID;
const apiKey = process.env.YOUTUBE_API_KEY;
assert.ok(clientId && clientSecret && channelId && apiKey, 'GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET, YOUTUBE_CHANNEL_ID and YOUTUBE_API_KEY are set');
const redirectUri = 'http://localhost:3000/oauth2callback';
const receipt = 'youtube-video.json';
const title = 'Emberfall: first look';
const api = 'https://www.googleapis.com/youtube/v3';
async function json(res, what, status = 200) {
  const body = await res.json();
  assert.equal(res.status, status, what + ': ' + res.status + ' ' + JSON.stringify(body));
  return body;
}
async function token(params) {
  const res = await fetch('https://oauth2.googleapis.com/token', { method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, ...params }) });
  return json(res, 'token ' + params.grant_type);
}
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receipt, 'utf8'));
  const list = await json(await fetch(api + '/videos?part=snippet,status&id=' + saved.video, { headers: { 'X-Goog-Api-Key': apiKey } }), 'videos.list');
  assert.equal(list.items.length, 1);
  assert.equal(list.items[0].snippet.title, title);
  assert.equal(list.items[0].snippet.channelId, channelId);
  assert.equal(list.items[0].status.uploadStatus, 'processed');
  console.log(JSON.stringify({ retained: true, video: saved.video, title }));
} else {
  // 1. the authorization request: Google's account chooser
  const scope = 'https://www.googleapis.com/auth/youtube.force-ssl https://www.googleapis.com/auth/youtube.upload';
  const authorize = new URL('https://accounts.google.com/o/oauth2/v2/auth');
  for (const [k, v] of Object.entries({ client_id: clientId, redirect_uri: redirectUri, response_type: 'code', scope, access_type: 'offline', state: 'first-use' })) authorize.searchParams.set(k, v);
  const page = await fetch(authorize);
  assert.equal(page.status, 200);
  const html = await page.text();
  // 2. the person chooses their account: the chooser's form for it, posted as the browser posts it
  const unescape = (s) => s.replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
  const form = /<form method="post" action="([^"]+)"><input type="hidden" name="request" value="([^"]*)"><input type="hidden" name="sub" value="([^"]*)">/.exec(html);
  assert.ok(form, 'the account chooser offers an account');
  const chosen = await fetch(new URL(form[1], authorize), { method: 'POST', redirect: 'manual', headers: { 'content-type': 'application/x-www-form-urlencoded' }, body: new URLSearchParams({ request: unescape(form[2]), sub: unescape(form[3]) }) });
  assert.equal(chosen.status, 302);
  const back = new URL(chosen.headers.get('location'));
  assert.equal(back.origin + back.pathname, redirectUri);
  assert.equal(back.searchParams.get('state'), 'first-use');
  const code = back.searchParams.get('code');
  assert.ok(code, 'Google returned a code');
  // 3. the code for tokens
  const granted = await token({ grant_type: 'authorization_code', code, redirect_uri: redirectUri });
  assert.equal(granted.token_type, 'Bearer');
  assert.ok(granted.access_token && granted.refresh_token, 'an access token and, for offline access, a refresh token');
  assert.ok(granted.scope.split(' ').includes('https://www.googleapis.com/auth/youtube.upload'));
  const auth = { authorization: 'Bearer ' + granted.access_token };
  // 4. the person's channel
  const mine = await json(await fetch(api + '/channels?part=id,snippet&mine=true', { headers: auth }), 'channels.list');
  assert.equal(mine.items[0].id, channelId);
  // 5. a video, uploaded by the resumable protocol
  const bytes = new TextEncoder().encode('EMBERFALL-FIRST-LOOK-SYNTHETIC');
  const start = await fetch('https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status', {
    method: 'POST', headers: { ...auth, 'content-type': 'application/json; charset=UTF-8', 'x-upload-content-length': String(bytes.length), 'x-upload-content-type': 'video/mp4' },
    body: JSON.stringify({ snippet: { title, description: 'A first look at Emberfall.', categoryId: '20' }, status: { privacyStatus: 'public' } }),
  });
  assert.equal(start.status, 200);
  const session = start.headers.get('location');
  assert.match(session, /upload_id=/);
  const video = await json(await fetch(session, { method: 'PUT', headers: { ...auth, 'content-type': 'video/mp4' }, body: bytes }), 'upload', 201);
  assert.equal(video.snippet.title, title);
  assert.equal(video.snippet.channelId, channelId);
  assert.equal(video.status.uploadStatus, 'uploaded');
  // 6. the refresh token renews the access token, which reads the video back
  const renewed = await token({ grant_type: 'refresh_token', refresh_token: granted.refresh_token });
  assert.ok(renewed.access_token && renewed.access_token !== granted.access_token);
  const read = await json(await fetch(api + '/videos?part=snippet,status&id=' + video.id, { headers: { authorization: 'Bearer ' + renewed.access_token } }), 'videos.list');
  assert.equal(read.items[0].status.uploadStatus, 'processed');
  writeFileSync(receipt, JSON.stringify({ video: video.id, channel: channelId }) + '\n');
  console.log(JSON.stringify({ signedIn: true, channel: channelId, video: video.id, title, uploadStatus: read.items[0].status.uploadStatus }));
}
